private void switchToSearchFragment(Bundle savedInstanceState){
  if (savedInstanceState == null) {
    OCFileListFragment listOfFiles=new OCFileListFragment();
    Bundle args=new Bundle();
    args.putParcelable(OCFileListFragment.SEARCH_EVENT,getIntent().getParcelableExtra(OCFileListFragment.SEARCH_EVENT));
    args.putBoolean(OCFileListFragment.ARG_ALLOW_CONTEXTUAL_ACTIONS,true);
    listOfFiles.setArguments(args);
    try {
      FragmentTransaction transaction=getSupportFragmentManager().beginTransaction();
      transaction.add(R.id.left_fragment_container,listOfFiles,TAG_LIST_OF_FILES);
      transaction.commit();
    } catch (IllegalStateException e) {
      // Ignore or log; transaction could not be committed due to state loss
    }
  }
 else {
    getSupportFragmentManager().findFragmentByTag(TAG_LIST_OF_FILES);
  }
}
